    "html": "<div class=\"content-container\">\n            <h1>Code 6</h1>\n            <div class=\"code-box\">\n                <p>\n                    #server.py\n                    <br>import socket\n                    <br>from ch import c\n                    <br>s=socket.socket(socket.AF_INET,socket.SOCK_RAW,socket.IPPROTO_ICMP)\n                    <br>while True:\n                    <br>p,_=s.recvfrom(1024)\n                    <br>if p[20]==8:\n                    <br>print(\"Received:\",p[28:])\n                    <br>print(\"Checksum:\", \"OK\" if c(p[20:])==0 else \"Fail\")\n                    <br>\n                    <br>#ch.py\n                    <br>def c(d):\n                    <br>s=0\n                    <br>for i in range(0,len(d),2):\n                    <br>w=(d[i] &lt; &lt; 8)+(d[i+1] if i+1&lt;len(d) else 0) s=(s+w)&0xffff return (~s)&0xffff #client.py<br>\n                        <br>    import socket,os,struct<br>\n                        <br>from ch import c\n                        <br>s=socket.socket(socket.AF_INET,socket.SOCK_RAW,socket.IPPROTO_ICMP)\n                        <br>d=b\"data\"\n                        <br>id=os.getpid()&0xffff\n                        <br>p=struct.pack(\"!BBHHH\",8,0,0,id,1)+d\n                        <br>ck=c(p)\n                        <br>p=struct.pack(\"! BBHHH \",8,0,ck,id,1) +d\n                        <br>s.sendto(p,(\" localhost \" , 0 ) )\n                </p>\n            </div>\n        </div>"
