    "html": "<div class=\"content-container\">\n            <h1>Swap two numbers without using temporary variables</h1>\n            <div class=\"code-box\">\n                <p>\n                    #include &#60 stdio.h&#62<br>\n                        int main()<br>\n                        {<br>\n                        int a=10, b=20;<br>\n                        printf(\"Before swap a=%d b=%d\",a,b);<br>\n                        a=a+b;//a=30 (10+20)<br>\n                        b=a-b;//b=10 (30-20)<br>\n                        a=a-b;//a=20 (30-10)<br>\n                        printf(\"\\nAfter swap a=%d b=%d\",a,b);<br>\n                        return 0;<br>\n                        }<br>\n                </p>\n            </div>\n        </div>\n        <div class=\"content-container\">\n            <h1>Swap with using temporary variables</h1>\n            <div class=\"code-box\">\n                <p>\n                    #include &#60 stdio.h&#62<br>\n                        int main()<br>\n                        {<br>\n                        int a=10, b=20;<br>\n                        printf(\"Before swap a=%d b=%d\",a,b);<br>\n                        int temp=a;<br>\n                        a=b;<br>\n                        b=temp;<br>\n                        printf(\"\\nAfter swap a=%d b=%d\",a,b);<br>\n                        return 0;<br>\n                        }<br>\n                </p>\n            </div>\n        </div>\n        <div class=\"content-container\">\n            <h1>Swap two numbers without using temporary variables</h1>\n            <div class=\"code-box\">\n                <p>\n                    #include &#60 stdio.h&#62<br>\n                        int main()<br>\n                        {<br>\n                        int a=10, b=20;<br>\n                        printf(\"Before swap a=%d b=%d\",a,b);<br>\n                        swap(a,b);<br>\n                        printf(\"\\nAfter swap a=%d b=%d\",a,b);<br>\n                        return 0;<br>\n                        }<br>\n                </p>\n            </div>\n        </div>"
