    "title": "Palindrome",
    "html": "<div class=\"content-container\">\n            <h1>Palindrome</h1>\n            <div class=\"code-box\">\n                <p>\n                    public class five {<br>\n                    public static void main(String[] args) {<br>\n                    int num = 3553, reversedNum = 0, remainder;<br>\n                    int originalNum = num;<br>\n                    while (num != 0) {<br>\n                    remainder = num % 10;<br>\n                    reversedNum = reversedNum * 10 + remainder;<br>\n                    num /= 10;<br>\n                    }<br>\n                    if (originalNum == reversedNum) {<br>\n                    System.out.println(originalNum + \" is Palindrome.\");<br>\n                    }<br>\n                    else {<br>\n                    System.out.println(originalNum + \" is not Palindrome.\");<br>\n                    }<br>\n                    }<br>\n                    }<br>\n                </p>\n            </div>\n        </div>"
