    "title": "Bitwise Operators",
    "html": "<div class=\"content-container\">\n            <h1>Bitwise Operators</h1>\n            <div class=\"code-box\">\n                <p>\n                    class onec {<br>\n                    public static void main(String[] args) {<br>\n                    int number1 = 12, number2 = 25, result;<br>\n                    // bitwise OR between 12 and 25<br>\n                    result = number1 | number2;<br>\n                    System.out.println(result);<br>\n                    // prints 29<br>\n                    // bitwise AND between 12 and 25<br>\n                    result = number1 & number2;<br>\n                    System.out.println(result);<br>\n                    // prints 8<br>\n                    }<br>\n                    }<br>\n                </p>\n            </div>\n        </div>"
