    "title": "Ditctionary",
    "html": "<div class=\"content-container\">\n            <h1>Ditctionary</h1>\n            <div class=\"code-box\">\n                <p> numdict = {'one': 1, 'two': 2, 'three': 3, 'four': 4}<br>\n                    print(\"Displaying Dictionary-\\n\", numdict)<br>\n                </p>\n            </div>\n        </div>"
